export function ControlIcon({ icon }: { icon: ControlButtonIcon }) {
  switch (icon) {
    case "prev":
      return <PreviousIcon />;
    case "next":
      return <NextIcon />;
    case "pause":
      return <PauseIcon />;
    case "play":
      return <PlayIcon />;
  }
}

